 const [user,setUser]=useState<User|null>(null),[authReady,setAuthReady]=useState(false),[needsSetup,setNeedsSetup]=useState(false),[editRecord,setEditRecord]=useState<Row|null>(null),[paymentOrder,setPaymentOrder]=useState<number|undefined>();
 const [company,setCompany]=useState<Company>({name:'Enterprise SAC',taxId:'20100000001',email:'contacto@enterprise.local',phone:'',address:'Lima, Perú'});
