 function go(p:string){setCsvKind(null);setOperationDetail(null);setOperationView('orders');setQuoteId(undefined);setInvoiceOrderId(undefined);if(p==='Finanzas')p='Pagos';if(adminPages[p]&&user?.role!=='Administrador')p='Dashboard';setPage(p);history.replaceState(null,'',pageHash(p));setSearch('');setFilter('Todos');setSelected(null);setModal(null);setNotifications(false)}
