 function table(items:Row[],kind:string){return <div className="table-scroll"><table><thead><tr>{kind==='products'?<><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Disponibilidad</th></>:kind==='customers'||kind==='suppliers'?<><th>{kind==='customers'?'Cliente':'Proveedor'}</th><th>Documento</th><th>Contacto</th><th>Estado</th></>:kind==='audit'?<><th>Actividad</th><th>Módulo</th><th>Usuario</th><th>Fecha</th></>:<><th>{kind==='payments'?'Movimiento':'N.º de operación'}</th><th>{kind==='purchases'||(kind==='accounts'&&page==='Cuentas por pagar')?'Proveedor':['accounts','payments'].includes(kind)?'Entidad':'Cliente'}</th><th>Fecha</th><th>{kind==='accounts'?'Saldo pendiente':'Importe'}</th><th>Estado</th></>}<th/></tr></thead><tbody>{items.map(r=><tr key={r.id} onClick={()=>openRecord(r,kind)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'&&e.target===e.currentTarget)openRecord(r,kind)}}>{kind==='products'?<><td><div className="entity"><span className="product-icon"><Package size={19}/></span><div><strong>{r.name}</strong><small>{r.sku}</small></div></div></td><td>{r.category}</td><td className="numeric">{money(r.price)}</td><td>{r.stock} <small>unid.</small></td><td>{badge(r.stock<r.minimum?'Stock bajo':'Activo')}</td></>:kind==='customers'||kind==='suppliers'?<><td><div className="entity"><span className="avatar soft">{r.name.slice(0,2).toUpperCase()}</span><strong>{r.name}</strong></div></td><td><strong>{documentType(r)}</strong><small className="block">{r.taxId}</small></td><td>{r.email}<small className="block">{r.phone}</small></td><td>{badge(r.status)}</td></>:kind==='audit'?<><td><strong>{r.name}</strong><small className="block">Registro #{r.reference}</small></td><td>{r.module}</td><td>{r.user}</td><td>{date(r.date)}</td></>:<><td><strong>{r.reference}</strong><small className="block">{kind==='payments'?`${r.type} · ${r.method||'No especificado'}`:(r._kind||kind)==='sales'?'Venta directa':'Compra recibida'}</small></td><td><div className="entity"><span className={'avatar avatar-'+r.id%4}>{r.name.split(' ').map((s:string)=>s[0]).slice(0,2).join('')}</span>{r.name}</div></td><td>{date(r.date)}</td><td className="numeric"><strong>{money(kind==='accounts'?r.amount-r.paid:r.amount)}</strong></td><td>{badge(r.status)}</td></>}<td>{['sales','purchases'].includes(kind)?<div className="operation-row-actions" onClick={e=>e.stopPropagation()} onKeyDown={e=>e.stopPropagation()}><button className="btn" aria-label={'Comprobante de '+r.reference} onClick={()=>showOperation(kind,'invoices',r.id)}><Files size={14}/> {kind==='sales'?(r.invoice?.type||r.receiptType||'Comprobante'):'Factura'}</button><button className="btn" aria-label={'Seguimiento de '+r.reference} onClick={()=>showOperation(kind,'tracking',r.id)}><Activity size={14}/> Seguimiento</button></div>:<ArrowUpRight size={16} className="muted"/>}</td></tr>)}</tbody></table>{!items.length&&<div className="empty"><Search size={30}/><h3>{search||filter!=='Todos'?'Sin resultados':'Todo empieza con un registro'}</h3><p>{search?'Prueba con otro término de búsqueda.':'Los registros de este módulo aparecerán aquí.'}</p></div>}</div>}
