function EntryForm({kind,data,busy,send,initialOrderId,onDirty}:{kind:string;data:Data;busy:boolean;send:(path:string,body:object)=>Promise<void>;initialOrderId?:number;onDirty?:(dirty:boolean)=>void}){
 const [confirmation,setConfirmation]=useState<{path:string;body:object}|null>(null);
 const stage=(path:string,body:object)=>setConfirmation({path,body});
 const [lines,setLines]=useState<{productId:number;quantity:number}[]>([]);
 const [productNotice,setProductNotice]=useState('');
 const isQuote=kind==='quote',isSale=kind==='sale'||isQuote,isOrder=isSale||kind==='purchase';
 const [orderId,setOrderId]=useState(String(initialOrderId||''));
 const [contactId,setContactId]=useState('');
 const [method,setMethod]=useState(''),[payNow,setPayNow]=useState(false);
 const selectedContact=data[isSale?'customers':'suppliers'].find(r=>r.id===Number(contactId));
 const saleReceipt=selectedContact&&documentType(selectedContact)==='DNI'?'Boleta':'Factura';
 useEffect(()=>{onDirty?.(!!(contactId||lines.length||confirmation||payNow||!!method))},[contactId,lines,confirmation,payNow,method,onDirty]);
 const pending=[...data.sales,...data.purchases].filter(r=>r.status!=='Anulado'&&r.amount>r.paid);
 const quantityLimit=(product:Row)=>Math.max(0,Math.min(100000,isQuote?100000:isSale?product.stock:1000000-product.stock));
 function selectProduct(value:string){
  if(busy)return;
  const product=data.products.find(p=>p.id===Number(value));
  if(!product)return;
  const existing=lines.find(line=>line.productId===product.id);
  if((existing?.quantity||0)>=quantityLimit(product)){
   setProductNotice(isSale&&!isQuote?`No hay más existencias disponibles de ${product.name}.`:`Se alcanzó el límite de unidades de ${product.name}.`);return;
  }
  if(!existing&&lines.length>=100){setProductNotice('Puedes seleccionar hasta 100 productos por operación.');return;}
  setProductNotice('');
  setLines(previous=>{
   const current=previous.find(line=>line.productId===product.id);
   if((current?.quantity||0)>=quantityLimit(product)||(!current&&previous.length>=100))return previous;
   return current?previous.map(line=>line.productId===product.id?{...line,quantity:line.quantity+1}:line):[...previous,{productId:product.id,quantity:1}];
  });
 }
 function changeQuantity(productId:number,delta:number){
  if(busy)return;
  const product=data.products.find(p=>p.id===productId);
  if(!product)return;
  setProductNotice('');
  setLines(previous=>previous.map(line=>{
   if(line.productId!==productId)return line;
   const quantity=line.quantity+delta;
   return quantity>=1&&(delta<0||quantity<=quantityLimit(product))?{...line,quantity}:line;
  }));
 }
 const missing=isOrder?(!data[isSale?'customers':'suppliers'].length?(isSale?'Registra un cliente antes de crear una venta.':'Registra un proveedor antes de recibir una compra.'):!data.products.length?'Registra un producto antes de continuar.':''):kind==='payment'&&!pending.length?'No hay operaciones con saldo pendiente.':'';
 const remaining=pending.find(r=>r.id===Number(orderId));
 function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if((kind==='payment'||(isSale&&!isQuote&&payNow))&&!method)return;if(isOrder){if(!contactId||!lines.length)return;stage(isQuote?'quotes':'orders/'+(isSale?'sales':'purchases'),{contactId:Number(f.contactId),lines,...(!isQuote&&isSale?{emitReceipt:true,receiptDueDate:f.receiptDueDate,initialPayment:payNow?{method:f.method,paymentReference:f.paymentReference}:null}:{}),...(isQuote?{validUntil:f.validUntil,deliveryDate:f.deliveryDate,paymentDays:Number(f.paymentDays),notes:f.notes}:{})});}else if(kind==='product'){stage('products',{...f,price:Number(f.price),cost:Number(f.cost),stock:Number(f.stock),minimum:Number(f.minimum)})}else if(kind==='payment'){if(!remaining)return;stage('payments',{orderId:Number(f.orderId),amount:Number(f.amount),method:f.method,paymentReference:f.paymentReference})}else{stage('contacts/'+(kind==='customer'?'customers':'suppliers'),f)}}
 const draft=confirmation?.body as {amount?:number;method?:string;paymentReference?:string;initialPayment?:{paymentReference?:string}}|undefined;
 const paymentRef=kind==='payment'?draft?.paymentReference:draft?.initialPayment?.paymentReference;
 const confirmationPanel=confirmation?<div className="invoice-confirm" role="alert">
  <Check size={24}/><h3>¿Confirmar {isOrder?'la operación':kind==='payment'?'el pago':'el registro'}?</h3>
  <p>{isQuote?'Se guardará la propuesta sin mover existencias ni generar deuda.':isOrder?'Se guardará la operación y se actualizarán las existencias.':kind==='payment'?'Se registrará el importe y se actualizará el saldo pendiente.':'Se guardarán los datos ingresados.'}</p>
  {isOrder&&<p>Total: <strong>{money(lines.reduce((total,line)=>{const product=data.products.find(p=>p.id===line.productId)!;return total+line.quantity*(isSale?product.price:product.cost)},0))}</strong></p>}
  {isSale&&!isQuote&&<><p>Se generará: <strong>{saleReceipt}</strong> para {selectedContact?.name} ({documentType(selectedContact)} {selectedContact?.taxId}).</p><p>Cobro: <strong>{payNow?method:'Pendiente'}</strong></p></>}
  {kind==='payment'&&<><p>Importe: <strong>{money(Number(draft?.amount))}</strong></p><p>Método: <strong>{draft?.method}</strong></p></>}
  {paymentRef&&<p>Referencia: {paymentRef}</p>}
  <div className="invoice-actions"><button className="btn" disabled={busy} onClick={()=>setConfirmation(null)}>Volver</button><button className="btn primary" disabled={busy} onClick={async()=>{await send(confirmation.path,confirmation.body);setConfirmation(null)}}>{busy?'Guardando…':'Sí, confirmar'}</button></div>
 </div>:null;

 return <>{confirmationPanel}<form hidden={!!confirmation} style={confirmation?{display:'none'}:undefined} onSubmit={submit}>{missing&&<p className="inline-error" role="status">{missing}</p>}<p className="form-intro">{isOrder?(isQuote?'La cotización conserva los precios actuales sin descontar stock.':isSale?'Confirma la venta para descontar el stock de tu almacén.':'Registra una compra recibida para incrementar las existencias.'):'Completa los datos para guardar el registro.'}</p>{isOrder?<><SearchPicker buttonLabel={isSale?'Seleccionar cliente':'Seleccionar proveedor'} label={isSale?'Cliente':'Proveedor'} placeholder="Buscar por nombre, RUC o DNI" name="contactId" disabled={busy} value={contactId} onChange={setContactId} options={data[isSale?'customers':'suppliers'].map(r=>({value:String(r.id),label:r.name,detail:`${documentType(r)}: ${r.taxId}`,search:`${r.name} ${r.taxId}`}))}/>{isQuote&&<><div className="form-grid"><label>Válida hasta<input required type="date" name="validUntil" min={new Date().toLocaleDateString('sv-SE',{timeZone:'America/Lima'})}/></label><label>Entrega prevista<input required type="date" name="deliveryDate" min={new Date().toLocaleDateString('sv-SE',{timeZone:'America/Lima'})}/></label><label>Plazo de pago (días)<input required type="number" name="paymentDays" min="0" max="365" defaultValue="30"/></label></div><label>Observaciones<textarea name="notes" maxLength={1000} placeholder="Condiciones comerciales y entrega"/></label></>}{!isQuote&&isSale&&<div className="sale-receipt-summary"><strong>Comprobante: {saleReceipt}</strong><p>{selectedContact?`${documentType(selectedContact)}: ${selectedContact.taxId}`:'Selecciona un cliente para determinar el comprobante.'}</p><label>Vencimiento del comprobante<input type="date" name="receiptDueDate" required min={new Date().toLocaleDateString('sv-SE',{timeZone:'America/Lima'})} defaultValue={new Date().toLocaleDateString('sv-SE',{timeZone:'America/Lima'})}/></label><small>Se genera automáticamente al confirmar la venta.</small><div className="sale-payment-option"><input id="pay-sale-now" type="checkbox" checked={payNow} onChange={event=>setPayNow(event.target.checked)}/><label htmlFor="pay-sale-now">Registrar el cobro de esta venta ahora</label></div>{payNow?<PaymentFields method={method} onChange={setMethod} busy={busy}/>:<p className="form-note">Queda pendiente de cobro. El método se registrará al cobrar.</p>}</div>}<div className="order-product-picker"><SearchPicker buttonLabel={lines.length?'Seleccionar otro producto':'Seleccionar producto'} label="Producto" placeholder="Buscar por nombre o código" disabled={busy} value="" onChange={selectProduct} options={data.products.map(p=>({value:String(p.id),label:p.name,detail:`${p.sku} · ${p.stock} unid. · ${money(isSale?p.price:p.cost)}`,search:`${p.name} ${p.sku}`}))}/></div>
{productNotice&&<p className="form-note" role="status">{productNotice}</p>}
<div className="order-lines">{lines.length?lines.map(l=>{
 const p=data.products.find(p=>p.id===l.productId)!;
 const atLimit=l.quantity>=quantityLimit(p);
 return <div key={l.productId} className="order-product-row">
  <span className="order-product-info"><strong title={p.name}>{p.name}</strong><small>{money(isSale?p.price:p.cost)} por unidad</small></span>
  <div className="line-quantity" role="group" aria-label={'Cantidad de '+p.name}>
   <button type="button" aria-label={'Reducir cantidad de '+p.name} disabled={busy||l.quantity<=1} onClick={()=>changeQuantity(l.productId,-1)}><Minus size={14}/></button>
   <output aria-label={'Unidades de '+p.name} aria-live="polite">{l.quantity}</output>
   <button type="button" aria-label={'Aumentar cantidad de '+p.name} title={atLimit?'Límite de unidades alcanzado':'Aumentar cantidad'} disabled={busy||atLimit} onClick={()=>changeQuantity(l.productId,1)}><Plus size={14}/></button>
  </div>
  <strong className="order-product-subtotal">{money(l.quantity*(isSale?p.price:p.cost))}</strong>
  <button type="button" aria-label={'Quitar '+p.name} disabled={busy} className="icon-button order-product-remove" onClick={()=>{setProductNotice('');setLines(previous=>previous.filter(x=>x.productId!==l.productId))}}><X size={15}/></button>
 </div>
}):<p>Selecciona un producto para agregarlo a la operación.</p>}</div><div className="order-total"><span>Total de la operación</span><strong>{money(lines.reduce((a,l)=>{const p=data.products.find(p=>p.id===l.productId)!;return a+l.quantity*(isSale?p.price:p.cost)},0))}</strong></div><small className="form-note">{isQuote?'Importes finales en PEN. La cotización no genera un saldo por cobrar.':'Importes finales en PEN. La operación queda pendiente de pago.'}</small></>:kind==='product'?<><label>Nombre del producto<input name="name" required minLength={2} placeholder="Ej. Monitor profesional 27″" maxLength={160}/></label><div className="form-grid"><label>SKU<input name="sku" required minLength={2} placeholder="TEC-007" maxLength={40}/></label><label>Categoría<input name="category" required minLength={2} placeholder="Tecnología" maxLength={60}/></label><label>Precio de venta (S/)<input name="price" type="number" max="9999999999.99" min="0.01" step="0.01" required/></label><label>Costo (S/)<input name="cost" type="number" max="9999999999.99" min="0" step="0.01" required/></label><label>Stock inicial<input name="stock" type="number" min="0" max="1000000" required/></label><label>Stock mínimo<input name="minimum" type="number" min="0" max="1000000" defaultValue="10" required/></label></div></>:kind==='payment'?<><SearchPicker buttonLabel="Seleccionar operación" label="Operación pendiente" placeholder="Buscar por referencia o empresa" name="orderId" disabled={busy} value={orderId} onChange={setOrderId} options={pending.map(r=>({value:String(r.id),label:`${r.reference} - ${r.name}`,detail:`Saldo: ${money(r.amount-r.paid)}`,search:`${r.reference} ${r.name}`}))}/><label>Importe a registrar (S/)<input type="number" name="amount" min="0.01" max={remaining?Number((remaining.amount-remaining.paid).toFixed(2)):undefined} step="0.01" required/></label><PaymentFields method={method} onChange={setMethod} busy={busy}/><small className="form-note">Admite pagos parciales. No se permiten importes mayores al saldo.</small></>:<ContactFields customer={kind==='customer'} busy={busy} onDirty={()=>onDirty?.(true)}/>}<button className="btn primary full submit" type="submit" disabled={busy||!!missing||((kind==='payment'||(isSale&&!isQuote&&payNow))&&!method)||(kind==='payment'&&!remaining)||(isOrder&&(!contactId||!lines.length))}>{busy?<RefreshCw size={16} className="spin"/>:<Check size={16}/>} {busy?'Guardando…':isQuote?'Guardar cotización':isOrder?'Confirmar operación':'Guardar registro'}</button></form></>
}
createRoot(document.getElementById('root')!).render(<App/>);
